"""Plot selected intensity maps generated by 04_run_fast_nearfields.lsf."""

import csv
import importlib.util
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
plot_spec = importlib.util.spec_from_file_location(
    "plot_nearfields", Path(__file__).with_name("04_plot_nearfields.py"))
base = importlib.util.module_from_spec(plot_spec)
plot_spec.loader.exec_module(base)

read_fields = base.read_fields
plot_maps = base.plot_maps


def main():
    """Render complete fast requests with scales shared by matched modes."""
    base.review.style()
    resonances = ROOT / "results" / "resonances_fast"
    nearfields = ROOT / "results" / "nearfields_fast"
    with (resonances / "nearfield_manifest.csv").open(newline="", encoding="utf-8") as stream:
        rows = list(csv.DictReader(stream))
    loaded = {}
    for row in rows:
        request_id = int(row["request_id"])
        stem = nearfields / f"request_{request_id}"
        if stem.with_suffix(".done").exists():
            data = read_fields(stem.with_suffix(".mat"))
            if abs(data["requested_wavelength_nm"] - float(row["wavelength_nm"])) > 1e-6:
                raise ValueError(f"Request wavelength mismatch: {stem}")
            loaded[request_id] = data
    for row in rows:
        request_id = int(row["request_id"])
        if request_id not in loaded:
            continue
        peers = [loaded[int(peer["request_id"])] for peer in rows
                 if int(peer["request_id"]) in loaded and peer["angle_deg"] == row["angle_deg"]
                 and peer["resonance_id"] == row["resonance_id"]]
        limits = {plane: max(float(data[f"E2_{plane}"].max()) for data in peers)
                  for plane in ("xy", "xz")}
        title = f"{row['case']}, {row['angle_deg']} degrees, {row['resonance_id']}"
        plot_maps(loaded[request_id], nearfields / f"request_{request_id}", title, limits)


if __name__ == "__main__":
    main()
